import json, ray, torch
from nemo_rl.environments.interfaces import EnvironmentInterface, EnvironmentReturn

def score(text, truth):
    try:
        obj = json.loads(text.strip())
    except ValueError:
        return 0.0, 0.0                      # not JSON at all
    ok_format = isinstance(obj, dict) and set(obj) == {"answer"}
    value = obj.get("answer") if isinstance(obj, dict) else None
    correct = str(value).strip() == str(truth).strip()
    return float(correct), float(ok_format)

@ray.remote
class JsonMathEnvironment(EnvironmentInterface):
    def __init__(self, cfg):
        self.cfg = cfg

    def step(self, message_log_batch, metadata):
        cor, fmt = [], []
        for log, meta in zip(message_log_batch, metadata):
            reply = [m["content"] for m in log if m["role"] == "assistant"][-1]
            c, f = score(reply, meta["ground_truth"])
            cor.append(c); fmt.append(f)
        n = len(message_log_batch)
        return EnvironmentReturn(
            observations=[{"role": "environment", "content": ""}] * n,
            metadata=metadata,
            next_stop_strings=[None] * n,
            rewards={"reward/correctness": torch.tensor(cor).cpu(),
                     "reward/format": torch.tensor(fmt).cpu()},
            terminateds=torch.ones(n).cpu(),
            answers=None,
        )

    def global_post_process_and_metrics(self, batch):
        acc = (batch["reward/correctness"] * batch["is_end"]).mean().item()
        return batch, {"accuracy": acc,
                       "format_rate": batch["reward/format"].mean().item()}

